UPDATE `locales_quest` SET `Details_loc4` = '毛尔奥格人曾经统治着岛上的大部分地区，但时代已经改变了，我们现在正在努力保持自己的完整。我们的另一个行动地点叫做Maul ogg Post，由烬腹领导，他是一个相当强大的食人魔。$B$B在内心深处，我仍然认为他还活着，我想让你去看看他，他坚持要留下来，甚至当我们因为蛇怪的问题而离开的时候。$B$B去看看他是否在那里，至少有他的踪迹。' WHERE `entry` = 40217 AND `Details_loc4` = '毛尔奥格人曾经统治着岛上的大部分地区，但时代已经改变了，我们现在正在努力保持自己的完整。我们的另一个行动地点叫做Maul ogg Post，由Embergut领导，他是一个相当强大的食人魔。$B$B在内心深处，我仍然认为他还活着，我想让你去看看他，他坚持要留下来，甚至当我们因为蛇怪的问题而离开的时候。$B$B去看看他是否在那里，至少有他的踪迹。';
