UPDATE `locales_quest` SET `Details_loc4` = '你做得很好，你拥有最全面的探险家的坚韧和力量。如果我们真的想让深潮消失，并让这些岛屿摆脱它们的存在，我们必须变得更加大胆。他们的领导是依偎在深潮密室，需要被根除。$B$返回密室，并对Shasza公主和海潮之王哈凯仕进行报复，他们需要为他们的罪行和敌意而被杀死。相信我，没有理由，也没有外交手段，完成这件事，也许纳迦就会散去。' WHERE `entry` = 40276 AND `Details_loc4` = '你做得很好，你拥有最全面的探险家的坚韧和力量。如果我们真的想让深潮消失，并让这些岛屿摆脱它们的存在，我们必须变得更加大胆。他们的领导是依偎在深潮密室，需要被根除。$B$返回密室，并对Shasza公主和Tidelord Hakash进行报复，他们需要为他们的罪行和敌意而被杀死。相信我，没有理由，也没有外交手段，完成这件事，也许纳迦就会散去。';
