UPDATE `locales_quest` SET `OfferRewardText_loc4` = '那么，你寻求我的智慧，是吗？ 很少有人敢冒险进入我的领域，更不用说寻求我的接见了。 说出你的目的，但要注意你的用词，因为我对闲聊没有耐心。$B$B<赛纳隆 的目光变得更加强烈，他的原始本能随时准备扑向最轻微的欺骗或不尊重的迹象。 他的狼群隐藏在阴影中，躁动不安，空气中弥漫着野性的能量。>$B$B记住，凡人，人与自然之间的联系是微妙的。 只要稍有失误，我的狼群就会毫不犹豫地向你释放愤怒。 现在，说出你的意图。' WHERE `entry` = 41047 AND `OfferRewardText_loc4` = '那么，你寻求我的智慧，是吗？ 很少有人敢冒险进入我的领域，更不用说寻求我的接见了。 说出你的目的，但要注意你的用词，因为我对闲聊没有耐心。$B$B<Cenerron 的目光变得更加强烈，他的原始本能随时准备扑向最轻微的欺骗或不尊重的迹象。 他的狼群隐藏在阴影中，躁动不安，空气中弥漫着野性的能量。>$B$B记住，凡人，人与自然之间的联系是微妙的。 只要稍有失误，我的狼群就会毫不犹豫地向你释放愤怒。 现在，说出你的意图。';
UPDATE `locales_quest` SET `Details_loc4` = '$c 万岁，我有消息要告诉你。$B$B我们收到了有人专门向你询问的一封信。 它来自加基森的一个侏儒。$B$B他们被称为 瑞亚斯。 我们被要求通知您，如果您有空，您应该去那里。' WHERE `entry` = 41099 AND `Details_loc4` = '$c 万岁，我有消息要告诉你。$B$B我们收到了有人专门向你询问的一封信。 它来自加基森的一个侏儒。$B$B他们被称为 Reas。 我们被要求通知您，如果您有空，您应该去那里。';
UPDATE `locales_quest` SET `Details_loc4` = '你好$c。 我们收到一封信，要求我们送你去东瘟疫之地。 这封信来自驻扎在那里的一名德鲁伊。 他们的名字是“莱茵”，可以在圣光之愿教堂找到他们。' WHERE `entry` = 41101 AND `Details_loc4` = '你好$c。 我们收到一封信，要求我们送你去东瘟疫之地。 这封信来自驻扎在那里的一名德鲁伊。 他们的名字是“Rayne”，可以在圣光之愿教堂找到他们。';
UPDATE `locales_quest` SET `Details_loc4` = '问候$c。 看起来你是时候重新开始做生意了。$B$BA 巴尔莫丹周围贫瘠之地的某个 凯科斯·击王 正在寻找“他值得信赖的伙伴”。 他保证会有机会发大财。' WHERE `entry` = 41102 AND `Details_loc4` = '问候$c。 看起来你是时候重新开始做生意了。$B$BA 巴尔莫丹周围贫瘠之地的某个 Kex Blowmaster 正在寻找“他值得信赖的伙伴”。 他保证会有机会发大财。';
UPDATE `locales_quest` SET `Details_loc4` = '你好 $c，看来你的搭档 凯科斯·击王 又来找你了。 他说所有的事情都已经准备好了，他希望你能在场见证他的伟大时刻。 在贝尔莫丹的贫瘠之地找到他。 毕竟你是贵宾。' WHERE `entry` = 41104 AND `Details_loc4` = '你好 $c，看来你的搭档 Kex Blowmaster 又来找你了。 他说所有的事情都已经准备好了，他希望你能在场见证他的伟大时刻。 在贝尔莫丹的贫瘠之地找到他。 毕竟你是贵宾。';
UPDATE `locales_quest` SET `Details_loc4` = '听着，$c！ 我现在有一件非常紧急和严重的事情需要你的帮助！$B$B那些吉尔尼斯人已经走了，再次打开了他们的大门，给我们带来了很多麻烦。 爆炸吧！ 现在他们的沿海炮台正在对我们的运输船进行猛烈攻击，使与幽暗城的贸易成为真正的痛苦！$B$BI 需要你照顾 炮兵莱尔森。 他是弗雷希尔要塞的恶棍，也是那些该死的大炮的指挥者。 你也不敢忘记他的追随者——把他们全部处理掉！$B$B一旦你把他送到了伟大的彼岸，就回来找我。 我们没有时间可以浪费。' WHERE `entry` = 41122 AND `Details_loc4` = '听着，$c！ 我现在有一件非常紧急和严重的事情需要你的帮助！$B$B那些吉尔尼斯人已经走了，再次打开了他们的大门，给我们带来了很多麻烦。 爆炸吧！ 现在他们的沿海炮台正在对我们的运输船进行猛烈攻击，使与幽暗城的贸易成为真正的痛苦！$B$BI 需要你照顾 Cannoneer Rileson。 他是弗雷希尔要塞的恶棍，也是那些该死的大炮的指挥者。 你也不敢忘记他的追随者——把他们全部处理掉！$B$B一旦你把他送到了伟大的彼岸，就回来找我。 我们没有时间可以浪费。';
